/* TDS 요약 규칙 (제품설명·일반명·용도·표면처리·선행/후속) */
const EXZ=t=>String(t||'').replace(/\s+/g,'');
const EXRES=[[/변성에폭시/,'변성 에폭시'],[/에폭시|epoxy/i,'에폭시'],[/폴리아스파틱|아스파틱/,'폴리아스파틱'],[/아크릴우레탄/,'아크릴 우레탄'],[/폴리우레탄/,'폴리우레탄'],[/우레탄|urethane/i,'우레탄'],[/아크릴|acrylic/i,'아크릴'],[/염화고무/,'염화고무'],[/알키드/,'알키드'],[/실리콘|silicone/i,'실리콘'],[/불소|fluor/i,'불소'],[/징크|아연/,'징크'],[/비닐|vinyl/i,'비닐'],[/무기질|규산/,'무기질']];
const EXCURE=[[/폴리아마이드|폴리아미드/,'폴리아마이드'],[/아민어덕트|아민애덕트/,'아민 어덕트'],[/폴리아민/,'폴리아민'],[/이소시아네이트/,'이소시아네이트']];
const EXPROP=[[/고(?:\(高\))?고형분|하이솔리드|highsolid/i,'고고형분'],[/후도막/,'후도막형'],[/속건/,'속건형'],[/무용제/,'무용제형'],[/저온/,'저온경화형']];
const EXPERF=[[/방청|방식|내식|녹방지/,'방청'],[/내마모/,'내마모'],[/내화학/,'내화학'],[/내후/,'내후'],[/내열/,'내열'],[/내수|방수/,'내수'],[/내충격/,'내충격'],[/부착|접착/,'부착'],[/방오/,'방오']];
const EXTG=[[/철구조물|강구조물/,'철구조물'],[/철재교량|강교|교량/,'교량'],[/파이프|배관/,'파이프'],[/탱크외부/,'탱크 외부'],[/탱크내부/,'탱크 내부'],[/탱크/,'탱크'],[/선체|선박/,'선박'],[/콘크리트/,'콘크리트'],[/플랜트/,'플랜트'],[/건축물|건축/,'건축물'],[/기계/,'기계류'],[/차량|철도/,'차량'],[/바닥/,'바닥'],[/철탑|송전/,'철탑'],[/해양구조물/,'해양구조물']];
const exFirst=t=>{const s=String(t||'').replace(/\s+/g,' ').trim();const m=s.match(/^(.+?(?:[다음임함]\.|\.)\s*)(.+?(?:[다음임함]\.|\.))?/);return m?(m[1]+(m[2]?' '+m[2]:'')).trim():s};
const exOrd=(z,a)=>a.map(([r,n])=>{const m=z.search(r);return m<0?null:[m,n]}).filter(Boolean).sort((x,y)=>x[0]-y[0]).map(x=>x[1]);
function exRes(z){const r=EXRES.find(x=>x[0].test(z));return r?r[1]:''}
function exLayer(z){const L=[];/하도|프라이머|primer/i.test(z)&&L.push('하도');/중도|중간도|intermediate/i.test(z)&&L.push('중도');/상도|마감|topcoat/i.test(z)&&L.push('상도');return L}
function exDesc(t,nm){const z=EXZ(exFirst(t));if(!z)return '';const res=exRes(z);if(!res)return '';
 const form=/2액형|2액|주제.{0,4}경화제/.test(z)?'2액형':/1액형|1액|단액/.test(z)?'1액형':'',cure=(EXCURE.find(x=>x[0].test(z))||[])[1],cm=cure&&new RegExp(cure.replace(/ /g,'')+'(?:경화형|경화제)').test(z),
 props=exOrd(z,EXPROP),perf=exOrd(z,EXPERF).slice(0,2),ly=exLayer(z),water=(window.WBX?WBX(z):/수성|수용성/.test(z)),
 role=ly.length>1?ly.slice(0,2).join('·')+(/겸용/.test(z)?' 겸용':''):ly[0]||'',
 end=/프라이머/.test(z)&&!/도료/.test(z)?'프라이머':'도료';
 const P=[form,cm?cure+' 경화형':'',(water?'수성 ':'')+res,props.slice(0,2).join(' '),perf.join('·'),role],
 build=a=>[...a.filter(Boolean),end].join(' ');
 let o=build(P);for(const k of [3,1,4]){if(o.length<=52)break;P[k]='';o=build(P)}return o}
/* exGen: 이전 정의 제거(뒤쪽 정의가 사용됨) */
function exUse(t){const z=EXZ(t);if(!z)return '';let a=exOrd(z,EXTG);if(a.includes('탱크 외부')||a.includes('탱크 내부'))a=a.filter(x=>x!='탱크');return a.slice(0,5).join('·')}
/* exSp: 이전 정의 제거(뒤쪽 정의가 사용됨) */
/* exPre: 이전 정의 제거(뒤쪽 정의가 사용됨) */
/* exApply: 이전 정의 제거(뒤쪽 정의가 사용됨) */

