const DXI={
 can:'<svg viewBox="0 0 48 48"><defs><linearGradient id="dxcn" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3b86f0"/><stop offset="1" stop-color="#0b4fd0"/></linearGradient></defs><ellipse cx="24" cy="12" rx="15" ry="4.5" fill="#c8d4e8"/><path d="M9 12v22c0 3 6.7 5.5 15 5.5S39 37 39 34V12c0 2.5-6.7 4.5-15 4.5S9 14.5 9 12z" fill="url(#dxcn)"/><path d="M12 8c0-5 24-5 24 0" fill="none" stroke="#8d9bb3" stroke-width="2.2" stroke-linecap="round"/><path d="M24 30c-5-1-8-5-7-10 5 0 8 4 7 10zm0 0c0-4 2-6 5-7" fill="#fff" stroke="#fff" stroke-width="1" stroke-linejoin="round"/></svg>',
 doc:'<path d="M7 3h7l5 5v13H7z"/><path d="M14 3v5h5M10 13h6M10 17h5"/>',
 brush:'<path d="M14 4l6 6-8 8H6v-6z"/><path d="M4 20l2-2"/>',
 box:'<path d="M12 3l8 4v10l-8 4-8-4V7z"/><path d="M4 7l8 4 8-4M12 11v10"/>',
 drop:'<path d="M12 3c-3.4 4.3-6 7.6-6 11a6 6 0 0 0 12 0c0-3.4-2.6-6.7-6-11z"/>',
 roller:'<rect x="4" y="3" width="13" height="6" rx="1.5"/><path d="M17 6h3v5h-8v4"/><rect x="10" y="15" width="4" height="6" rx="1"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 layers:'<path d="M12 3l9 5-9 5-9-5z"/><path d="M3 13l9 5 9-5"/>',
 calc:'<rect x="5" y="3" width="14" height="18" rx="2.5"/><path d="M8.5 7.5h7M9 12h.01M12 12h.01M15 12h.01M9 16h.01M12 16h.01M15 16h.01"/>'};
const dxSv=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${DXI[n]}</svg>`;
const DXO={},DXD=[];
function dbxTags(p){const T=[p.us,p.d,p.g,p.cat].filter(Boolean).join(' '),R=[[/방청|녹\s*방지|부식\s*방지/,'방청'],[/내마모/,'내마모'],[/내충격/,'내충격'],[/내화학/,'내화학'],[/내열/,'내열'],[/내후/,'내후'],[/방수/,'방수'],[/무용제/,'무용제'],[/내화/,'내화'],[/바닥/,'바닥']];return R.filter(r=>r[0].test(T)).slice(0,2).map(r=>r[1]).join(' · ')}
function dbxInfo(p){
 const m=mx(p),u=UN(p),two=m.b>0,fx=(l,v,o)=>{o=o||{};const e=v==null||v===''||v==='-';return `<div class="dxf${o.w?' w':''}${o.s3?' s3':''}"><span class="dxl">${l}</span><div class="dxv${e?' no':''}">${e?'-':(o.raw?v:esc(v))}${o.sfx&&!e?`<em>${o.sfx}</em>`:''}${o.cnt?`<i>${String(v||'').length}/${o.cnt}</i>`:''}</div></div>`},
 sc=(ic,t,body,x)=>{const k=p.n+'|'+t,op=DXO[k]!==undefined?DXO[k]:DXD.includes(t);return `<details class="dxs" data-k="${esc(k)}" ${op?'open':''} ontoggle="DXO[this.dataset.k]=this.open"><summary class="dxh"><span class="dxi">${dxSv(ic)}</span><b>${t}</b>${DBX.chev.replace('<svg class="','<svg class="dxc ')}</summary><div class="dxg${x?' '+x:''}">${body}</div></details>`};
 const tn=p.tn&&p.tn!='무희석'?p.tn+(p.tc&&p.tc!=p.tn?' ('+p.tc+')':''):'무희석';
 const R=String(p.dry||'').split(/[;\n]/).map(x=>x.trim()).filter(Boolean).map(r=>r.split('/').map(x=>x.trim())).sort((a,b)=>dbxTv(a)-dbxTv(b)),mc=R.find(c=>dbxTv(c)==20)||R[0];
 const dry=mc?[mc[1],mc[3]].filter(x=>x&&x!='-').join(' / '):'';
 const link=p.src?`<a href="${esc(p.src)}" target="_blank" rel="noopener">${esc(String(p.src).replace(/^https?:\/\//,'').slice(0,34))}</a>`:'';
 const area=thc(p)?(u=='kg'&&+p.sg>0?F(thc(p)/p.sg)+'㎡/kg':F(thc(p))+'㎡/L'):'';
 return sc('doc','기본 정보',fx('제품명',p.n)+fx('일반명',p.g)+fx('제품설명',p.d,{w:1,cnt:100})+fx('용도',p.us,{w:1}))
 +sc('brush','표면처리',fx('표면처리',p.sp,{w:1}))
 +sc('box','포장단위 / 혼합규격',fx('포장단위 (주제:경화제)',two?F(m.a)+u+' : '+F(m.b)+u:(+p.pk?F(+p.pk)+u:''))+fx('혼합규격',two?F(m.a/m.b,2)+' : 1 ('+(u=='kg'?'무게비':'부피비')+')':'단액형')+(p.pks?fx('데이터시트 포장규격',p.pks,{w:1}):''))
 +sc('drop','기본 물성',fx('단위',u)+fx(u=='kg'?'비중 (kg)':'비중',p.sg?F(+p.sg,2):'')+fx('고형분용적비 (SVR)',p.svr?p.svr+'%':''),'g3')
 +sc('roller','도장 사양',fx('혼합규격 (총량)',F(m.m)+u)+fx('추천도막 (1회도장)',p.dft,{sfx:'μm'})+fx('희석제 (규격)',tn)+fx('희석율 (%)',+p.tr?F(p.tr*100,1)+'%':'')+fx('이론 도장면적 (L·kg당 · 로스 제외)',rgT(p)?rgT(p).a:area,{s3:1})+fx('이론 소요량 (로스 제외 · 계산값과 동일)',rgT(p)?rgT(p).q:(thq(p)?F(thq(p),3)+(UN(p)=='kg'?' kg/㎡':' L/㎡'):''),{s3:1})+fx('혼합규격당 도장면적 (말당 면적)',rgT(p)&&rgT(p).c?rgT(p).c:(cov1(p)?F(cov1(p),1)+'㎡':''),{s3:1}),'g3')
 +sc('clock','건조/가사 시간',fx('건조시간 (지촉/경화)',dry)+fx('가사시간',p.pot)+(R.length?`<details class="dxm w"><summary>온도별 건조시간 · 재도장 간격 보기</summary>${dbxDry(p)}</details>`:''))
 +sc('layers','도장 시스템',fx('선행도장',p.pre)+fx('후속도장',p.nxt))
 +sc('doc','기타 정보',fx('출처',link||p.mf||'',{raw:!!link,w:1})+fx('TDS 개정일',p.rev)+fx('자료확인일',p.chk))
}

